//! SMA-755: Dogwood parses and replays the trace that the gateway encoder writes. The fixtures are
//! generated by `rs/crates/libs/paigasus-gateway-core/tests/decision_trace.rs`
//! (`PAIGASUS_WRITE_FIXTURES=1`). This is the proof that `dogwood replay` accepts our trace.

use dogwood_language::{Authorizer, Decision, PolicySchema, parse_trace};
use paigasus_policy_compiler::lower::{lower_units, service_schema, split_policies};

const SCHEMA: &str = include_str!("fixtures/test_schema.cedarschema");
const TRACE: &str = include_str!("fixtures/decision-trace.log");
const POLICY: &str = include_str!("fixtures/decision-trace.dw");
const EXPECTED: &str = include_str!("fixtures/decision-trace.expected.json");
const IDS_LOG: &str = include_str!("fixtures/decision-trace-ids.log");
const IDS_JSON: &str = include_str!("fixtures/decision-trace-ids.json");

fn verdicts() -> Vec<String> {
    let svc = service_schema();
    let units = split_policies(POLICY, &svc).expect("the policy parses");
    let schema = PolicySchema::from_cedarschema_str(SCHEMA).expect("the test schema parses");
    let mut authorizer = Authorizer::new(lower_units(&units, &svc, &schema).expect("the policy lowers"));
    parse_trace(TRACE)
        .expect("the trace parses")
        .iter()
        .map(|event| {
            let response = authorizer.is_authorized(event).expect("a request event is a decision");
            let errors: Vec<&str> = response.diagnostics().errors().collect();
            assert!(errors.is_empty(), "{errors:?}");
            match response.decision() {
                Decision::Allow => "ALLOW".to_owned(),
                Decision::Deny => "DENY".to_owned(),
            }
        })
        .collect()
}

#[test]
fn the_decision_trace_parses() {
    assert_eq!(parse_trace(TRACE).expect("parses").len(), 7);
}

#[test]
fn the_replay_gives_the_exact_verdict_sequence() {
    let expected: Vec<String> = serde_json::from_str(EXPECTED).expect("the expected file is a JSON array");
    let got = verdicts();
    assert_eq!(got, expected);
    let first_deny = got.iter().position(|v| v == "DENY").expect("the sequence holds a DENY");
    assert!(got[first_deny..].iter().any(|v| v == "ALLOW"), "an ALLOW follows a DENY");
    // The last record has a Cedar detail (two findings, `declared: "yes"`) and is allowed.
    assert_eq!(got.last().map(String::as_str), Some("ALLOW"));
}

#[test]
fn every_generated_action_id_round_trips() {
    let ids: Vec<String> = serde_json::from_str(IDS_JSON).expect("the ids file is a JSON array");
    let events = parse_trace(IDS_LOG).expect("the ids trace parses");
    assert!(ids.len() >= 100, "the generator keeps at least 100 ids, got {}", ids.len());
    assert!(ids.iter().any(|id| !id.is_ascii()), "an id has a non-ASCII char");
    assert!(ids.iter().any(|id| id.contains("::")), "an id has `::`");
    assert_eq!(events.len(), ids.len());
    for (event, id) in events.iter().zip(&ids) {
        assert_eq!(event.action(), id, "the parsed action id");
    }
}
